ruleToc.nextTocUrl:
@js:var page=result.match(/当前第\d+页，共(\d+)页，每页显示\d+章/)[1];
if(baseUrl.match(/1\/$/)){
	var url=baseUrl;
	}else{
		var go=baseUrl.replace(/.html/,"");
		var url=String(go+"/1/");
}
var list=[];
for(var i=2;i<=page;i++){
	list.push(url.replace(/1\/$/,i+"/"));
}
list;

ruleContent.nextContentUrl:
@js:
var rr = JSON.parse(result).result;
var c = JSON.parse(result).ajaxResult.code;
       if ( c != -1 ){
               if( rr.chapterNum < rr.pageCount )
               baseUrl=baseUrl.replace(/chapterId=\d+_?\d*/, 'chapterId=' + rr.nextChapterId );
         } else {
var r=java.ajax("https://m.sm.cn/api/rest?method=sc.novel_authorized&q="+ rr.bookName + "&source=纵横中文网");
        var hz=/&fr=.*?(?=")/.exec(r)[0];
        baseUrl=baseUrl.replace(/&fr=.*/,hz);
       }

